const batchSize = $('Configure Batch Size').first().json.BATCH_SIZE || 1;
const allItems = $input.all();

// Filter for rows where Status doesn't contain "Done"
const pendingItems = allItems.filter(item => {
  const status = item.json['Status'] || '';
  return !status.includes('Done');
});

if (pendingItems.length === 0) {
  throw new Error('No pending leads found. All rows are marked as Done.');
}

// Take the first batchSize items
const batchItems = pendingItems.slice(0, batchSize);

// Map Google Sheet column names to clean field names
return batchItems.map((item) => {
  const row = item.json;
  return {
    json: {
      _runTimestamp: new Date().toISOString(),
      first_name:         row['First Name']         || '',
      last_name:          row['Last Name']           || '',
      title:              row['Title']               || '',
      company_name:       row['Company Name']        || '',
      email:              row['Email']               || '',
      seniority:          row['Seniority']           || '',
      departments:        row['Departments']         || '',
      sub_departments:    row['Sub Departments']     || '',
      corporate_phone:    row['Corporate Phone']     || '',
      num_employees:      row['# Employees']         || '',
      industry:           row['Industry']            || '',
      keywords:           row['Keywords']            || '',
      person_linkedin_url:  row['Person Linkedin Url']  || '',
      website:              row['Website']              || '',
      company_linkedin_url: row['Company Linkedin Url'] || '',
      facebook_url:         row['Facebook Url']         || '',
      twitter_url:          row['Twitter Url']          || '',
      city:                 row['City']                 || '',
      state:                row['State']                || '',
      country:              row['Country']              || '',
      company_address:      row['Company Address']      || '',
      company_city:         row['Company City']         || '',
      company_state:        row['Company State']        || '',
      company_country:      row['Company Country']      || '',
      company_phone:        row['Company Phone']        || '',
      annual_revenue:       row['Annual Revenue']       || ''
    }
  };
});

const raw = $input.item.json.output || '';
const stripped = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/, '').trim();
let parsed;
try {
  parsed = JSON.parse(stripped);
} catch(e) {
  parsed = {
    researchSummary: raw,
    recentNews: 'N/A',
    painPoints: 'N/A',
    whyNow: 'N/A',
    personalizationHook: 'N/A',
    linkedinInsight: 'N/A',
    suggestedFreeWorkflow: 'business process automation workflow'
  };
}
return { json: { output: parsed } };

const raw = $input.item.json.output || $input.item.json.text || '';
let result = { subject: '', body: '' };

if (typeof raw === 'object' && raw !== null) {
  result.subject = raw.subject || (raw.output || {}).subject || '';
  result.body = raw.body || (raw.output || {}).body || '';
} else if (typeof raw === 'string') {
  let cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/, '').trim();
  try {
    const parsed = JSON.parse(cleaned);
    const inner = parsed.output || parsed;
    result.subject = inner.subject || '';
    result.body = inner.body || '';
  } catch(e) {
    result.subject = 'Quick question'; // Default fallback subject
    result.body = raw; // Just use the raw text as the body
  }
}
return { json: { output: result } };

const item = $input.item.json;
let contactId = null;
if (item.id) { contactId = item.id; }
if (!contactId && item.error) {
  const desc = (item.error.description || item.error.message || '');
  const match = desc.match(/Existing ID:\s*(\d+)/i);
  if (match) { contactId = match[1]; }
}
if (!contactId) {
  throw new Error('Could not resolve HubSpot contact ID. Raw: ' + JSON.stringify(item).slice(0, 200));
}
return { json: { contactId: contactId } };

